        roughness += float(l.get("roughness", 0.0)) * weight
        metallic += float(l.get("metallic", 0.0)) * weight
        height += float(l.get("height", 0.0)) * weight
        normal += _vec3(l.get("normal_ts", [0, 0, 1])) * weight
